snippets.lit:
import '@design-schema/lit';
import { html } from 'lit';
import type { BreadcrumbItem, BreadcrumbNavigateDetail } from '@design-schema/lit';

const shortTrail: BreadcrumbItem[] = [
  { label: 'Docs', href: '#docs' },
  { label: 'Components', href: '#components' },
  { label: 'Breadcrumb' },
];

html`
  <ds-breadcrumb
    .items=${shortTrail}
    @navigate=${(event: CustomEvent<BreadcrumbNavigateDetail>) => event.detail.originalEvent.preventDefault()}
  ></ds-breadcrumb>
`;

